INSERT INTO public.news_updates (title, description, content_type, image_url, video_url, link_url, is_active, is_featured, order_index) VALUES
('انطلاق دورة تحفيظ القرآن الكريم للأطفال', 'يسر شركة رواسخ أن تعلن عن انطلاق الدورة الصيفية لتحفيظ القرآن الكريم للأطفال من سن 6 إلى 12 سنة، مع نخبة من المعلمين المتميزين وبرنامج تعليمي متكامل.', 'news', 'https://images.unsplash.com/photo-1609599006353-e629aaabfeae?w=800', NULL, '/courses', true, true, 1),
('شرح طريقة استخدام منصة رواسخ التعليمية', 'فيديو تعريفي شامل يوضح كيفية التسجيل في المنصة، اختيار الكورسات المناسبة، وحضور الحصص الأونلاين بكل سهولة.', 'video', NULL, 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', NULL, true, true, 2),
('فعالية "يوم اللغة العربية" 2026', 'تدعوكم شركة رواسخ لحضور فعالية يوم اللغة العربية التي ستقام يوم 18 ديسمبر، وتتضمن مسابقات وورش عمل وجوائز قيمة لجميع المشاركين.', 'news', 'https://images.unsplash.com/photo-1488190211105-8b0e65b80b4e?w=800', NULL, '/contact', true, false, 3),
('نصائح لتحسين مهارات الإلقاء والخطابة', 'حلقة جديدة من سلسلة "تطوير الذات" نقدم فيها أهم النصائح العملية لتقوية مهارات الإلقاء وكسر حاجز الخوف من التحدث أمام الجمهور.', 'video', NULL, 'https://www.youtube.com/watch?v=jNQXAC9IVRw', NULL, true, false, 4),
('فتح باب التسجيل في برنامج تأهيل المعلمين', 'انطلاق التسجيل في الدفعة الجديدة من برنامج تأهيل المعلمين المعتمد من رواسخ، البرنامج يمتد لـ 3 أشهر مع شهادة معتمدة في النهاية.', 'news', 'https://images.unsplash.com/photo-1524178232363-1fb2b075b655?w=800', NULL, '/services', true, false, 5),
('قصص نجاح طلابنا - الموسم الأول', 'مجموعة من اللقاءات الملهمة مع طلاب رواسخ المتميزين الذين حققوا نتائج مبهرة، يشاركوننا تجاربهم ونصائحهم لباقي الطلاب.', 'video', NULL, 'https://www.youtube.com/watch?v=oHg5SJYRHA0', '/teachers', true, false, 6);